WITH focal AS (SELECT REPLACE(id_imovel,'-','') id_car_norm FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2019 AND 2024 AND id_car IS NOT NULL AND TRIM(id_car)!=''),mut AS (SELECT DISTINCT id_referencia_bacen,cpf,cnpj FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao BETWEEN 2019 AND 2024),edges AS (SELECT DISTINCT CONCAT('P_',SUBSTR(TO_HEX(SHA256(COALESCE(NULLIF(p.cpf,''),NULLIF(p.cnpj_basico,'')))),1,10)) propriedade_anon,CONCAT('M_',SUBSTR(TO_HEX(SHA256(COALESCE(NULLIF(mut.cpf,''),NULLIF(mut.cnpj,'')))),1,10)) mutuário_anon FROM p JOIN focal USING(id_car_norm) JOIN mut USING(id_referencia_bacen) WHERE COALESCE(NULLIF(p.cpf,''),NULLIF(p.cnpj_basico,'')) IS NOT NULL AND COALESCE(NULLIF(mut.cpf,''),NULLIF(mut.cnpj,'')) IS NOT NULL) SELECT * FROM edges ORDER BY propriedade_anon,mutuário_anon